# Prelude V v1 - literal bars (4/4, sixteenth units). U = R.H., L = L.H.  Both hands in continuous 16ths.
# Cell alluded to by the fugue subject: a rising 4th followed by a repeated-note 'tattoo' (x, x+4th, x+4th, x+4th).
U=[];L=[];TAG=[]
def S(s): return ' '.join(t if ':' in t else t+':1' for t in s.split())
def bar(u,l,tag=''):
    U.append(S(u) if ':' not in u else u); L.append(S(l) if ':' not in l else l); TAG.append(tag)
